/**
 * Continuità operativa migrazione SPID: somma al conteggio del nuovo userId anche quello dei task ancora
 * assegnati al vecchio userId quando l'operatore è migrato ({@code old_screen_name} valorizzato), coerentemente
 * con la semantica "numero di task assegnati". No-op per gli utenti non migrati.
 */
private long countOldUserTasks(List<String> tenantIds, long currentUserId, List<VariableQueryParameter> variableQueryParameters) throws CamundaClientException {
    Long oldUserId = oldUserResolver.getOldUserId(currentUserId);
    if (oldUserId == null) {
        return 0;
    }

    return camundaClient.countTasks(tenantIds, String.valueOf(oldUserId), null, variableQueryParameters);
}

private long correlateUser(HistoryVariable variable, List<HistoryUserOperation> operations) {
    return operations.stream().filter(op -> UserOperationCodes.CLAIM.equals(op.getOperation())).filter(op -> variable.getTimestamp().after(op.getTimestamp())).map(op -> op.getValue())
            .mapToLong(id -> {
                try {
                    return Long.parseLong(id);
                }
                catch (NumberFormatException e) {
                    log.warn("Operatore " + id);
                    return 0L;
                }
            }).findFirst().orElse(0L);
}

