public void dichiaraPartecipazione(ServiceContext serviceContext, long domandaBandoId, String variableSet, String variableVal, String commento, List<String> selezionati, long groupId, String portalURL) {
    try {
        DomandaBando domandaBando = domandaBandoLocalService.getDomandaBando(domandaBandoId);

        String taskId = getTaskId(domandaBando);

        String tenantId = String.valueOf(serviceContext.getScopeGroup().getOrganizationId());

        User currentUser = userLocalService.getUser(serviceContext.getUserId());

        if (selezionati != null && !selezionati.isEmpty()) {
            allegatoDomandaBandoLocalService.updateVisibilita(selezionati, true);
        }

        List<Task> tasksByBusinessKey = camundaClient.getTasksByBusinessKey(tenantId, String.valueOf(domandaBandoId));
        if (tasksByBusinessKey != null) {

            for (Task task : tasksByBusinessKey) {
                if (taskId.equalsIgnoreCase(task.getId()) && String.valueOf(currentUser.getUserId()).equalsIgnoreCase(task.getAssignee())) {
                    List<Entry<String, String>> variables = new ArrayList<>();

                    if (Validator.isNotNull(variableSet)) {
                        variables.add(new AbstractMap.SimpleEntry<>(variableSet, variableVal));
                    }
                    camundaClient.completeTask(taskId, variables);
                }
            }
        }

        if (Validator.isNotNull(commento)) {
            commentoDomandaBandoLocalService.addCommento(serviceContext, domandaBandoId, true, commento, taskId);
        }

        azioneOperatoreLocalService.addAzioneOperatore(serviceContext, domandaBandoId, serviceContext.getUserId(), new Date(),
                CustomProcessVariables.ESITO_PROCEDIMENTO_PARTECIPAZIONE_EFFETTUATA.equals(variableVal) ? AzioniOperatoreCodes.ESITO_PROCEDIMENTO_PARTECIPAZIONE_EFFETTUATA.name()
                        : AzioniOperatoreCodes.ESITO_PROCEDIMENTO_PARTECIPAZIONE_NON_EFFETTUATA.name());
    }
    catch (Exception e) {
        throw new RuntimeException(e);
    }
}

public void chiudiAvvisoSportello(ServiceContext serviceContext, long domandaBandoId, String variableSet, String variableVal, String commento, List<String> selezionati) {
    try {
        DomandaBando domandaBando = domandaBandoLocalService.getDomandaBando(domandaBandoId);

        String taskId = getTaskId(domandaBando);

        String tenantId = String.valueOf(serviceContext.getScopeGroup().getOrganizationId());

        User currentUser = userLocalService.getUser(serviceContext.getUserId());

        if (selezionati != null && !selezionati.isEmpty()) {
            allegatoDomandaBandoLocalService.updateVisibilita(selezionati, true);
        }

        List<Task> tasksByBusinessKey = camundaClient.getTasksByBusinessKey(tenantId, String.valueOf(domandaBandoId));
        if (tasksByBusinessKey != null) {

            for (Task task : tasksByBusinessKey) {

                //se la domanda non è stata presa in carico o l'assignee non corrisponde con l'utente che sta chiudendo le domande, assegno la domanda a quest'uòtimo prima di chiuderla
                if (Validator.isNull(task.getAssignee()) || task.getAssignee().isEmpty() || !String.valueOf(currentUser.getUserId()).equalsIgnoreCase(task.getAssignee())) {
                    camundaClient.claim(String.valueOf(serviceContext.getUserId()), taskId);
                }

                if (taskId.equalsIgnoreCase(task.getId()) && String.valueOf(currentUser.getUserId()).equalsIgnoreCase(task.getAssignee())) {
                    List<Entry<String, String>> variables = new ArrayList<>();

                    if (Validator.isNotNull(variableSet)) {
                        variables.add(new AbstractMap.SimpleEntry<>(variableSet, variableVal));
                    }
                    camundaClient.completeTask(taskId, variables);
                }
            }
        }

        if (Validator.isNotNull(commento)) {
            commentoDomandaBandoLocalService.addCommento(serviceContext, domandaBandoId, true, commento, taskId);
        }

        azioneOperatoreLocalService.addAzioneOperatore(serviceContext, domandaBandoId, serviceContext.getUserId(), new Date(),
                CustomProcessVariables.ESITO_PROCEDIMENTO_POSITIVO.equals(variableVal) ? AzioniOperatoreCodes.ESITO_PROCEDIMENTO_POSITIVO.name()
                        : AzioniOperatoreCodes.ESITO_PROCEDIMENTO_NEGATIVO.name());
    }
    catch (Exception e) {
        throw new RuntimeException(e);
    }
}

public void annullaAvvisoSportello(ServiceContext serviceContext, long domandaBandoId, String variableVal, String commento) {

    try {
        DomandaBando domandaBando = domandaBandoLocalService.getDomandaBando(domandaBandoId);

        String tenantId = String.valueOf(serviceContext.getScopeGroup().getOrganizationId());

        if (Validator.isNotNull(commento)) {
            commentoDomandaBandoLocalService.addCommento(serviceContext, domandaBandoId, true, commento, null);
        }

        camundaClient.updateProcessInstanceVariableByBusinessKey(domandaBando.getProcessInstanceId(), CamundaCodiciOperazioniUtente.ESITO_PROCEDIMENTO.getValue(), variableVal, "string");
        camundaClient.correlateMessage(tenantId, CustomProcessVariables.INTEGRAZIONI_ANNULLATE_MESSAGE, String.valueOf(domandaBando.getDomandaBandoId()));

        azioneOperatoreLocalService.addAzioneOperatore(serviceContext, domandaBandoId, serviceContext.getUserId(), new Date(),
                CustomProcessVariables.ESITO_PROCEDIMENTO_POSITIVO.equals(variableVal) ? AzioniOperatoreCodes.ESITO_PROCEDIMENTO_POSITIVO.name()
                        : AzioniOperatoreCodes.ESITO_PROCEDIMENTO_NEGATIVO.name());
    }
    catch (Exception e) {
        throw new RuntimeException(e);
    }
}

public void assegnaResponsabile(ServiceContext serviceContext, long domandaBandoId, String variableSet, String commento) {
    try {
        DomandaBando domandaBando = domandaBandoLocalService.getDomandaBando(domandaBandoId);

