public BigDecimal calcolaBudgetRimasto(long bandoId){
    try{
        BigDecimal budgetTotale = budgetBandoLocalService.getBudgetTotaleByBandoId(bandoId);

        List<String> statiDaEscludere = Arrays.asList(
                StatoDomandaBandoEnum.CHIUSA_NEGATIVAMENTE.name(),
                StatoDomandaBandoEnum.ASSENZA_GIUSTIFICATA.name(),
                StatoDomandaBandoEnum.ASSENZA_NON_GIUSTIFICATA.name(),
                StatoDomandaBandoEnum.ANNULLATA.name(),
                StatoDomandaBandoEnum.BOZZA.name(),
                StatoDomandaBandoEnum.PARTECIPAZIONE_EFFETTUATA.name()
        );
        BigDecimal budgetAssegnato = domandaBandoLocalService.getTotaleImportiAssegnatiByBandoIdAndStatoNotIn(bandoId,statiDaEscludere);

        if(Validator.isNotNull(budgetAssegnato) && Validator.isNotNull(budgetTotale)){
            return budgetTotale.subtract(budgetAssegnato);
        }
        return null;
    }catch (Exception e) {
        throw new RuntimeException(e);
    }
}

