	 * @param tenantId l'ID tenant Camunda
	 * @param userIdResponsabile l'ID dell'utente responsabile a cui assegnare la richiesta
	 * @param richiestaId l'ID della richiesta
	 * @param taskId l'ID del task da completare
	 * @param variableSet il nome della variabile di processo da impostare
	 * @param commento il commento opzionale da aggiungere
	 * @param serviceContext il contesto del servizio Liferay
	 * @throws PortalException se si verificano errori nell'assegnazione
	 */
	public void assegnaResponsabile(String tenantId, long userIdResponsabile, long richiestaId, String taskId, String variableSet, String commento, ServiceContext serviceContext) throws PortalException {

		User currentUser = userLocalService.getUser(serviceContext.getUserId());
		User responsabileUser = userLocalService.getUser(userIdResponsabile);

		List<Task> tasksByBusinessKey = camundaClient.getTasksByBusinessKey(tenantId, String.valueOf(richiestaId));
		if (tasksByBusinessKey != null) {

			for (Task task : tasksByBusinessKey) {
				if (taskId.equalsIgnoreCase(task.getId()) && String.valueOf(currentUser.getUserId()).equalsIgnoreCase(task.getAssignee())) {
					List<Entry<String, String>> variables = new ArrayList<Entry<String, String>>();

					if (Validator.isNotNull(variableSet)) {
						variables.add(new AbstractMap.SimpleEntry<String, String>(variableSet, String.valueOf(responsabileUser.getUserId())));
					}
					camundaClient.completeTask(taskId, variables);
				}
			}
		}

		// Aggiunta commento, se presente
		if (Validator.isNotNull(commento)) {
			commentoRichiestaLocalService.createCommentoRichiesta(commento, taskId, false, richiestaId, currentUser.getUserId(), currentUser.getFullName(), serviceContext.getScopeGroupId(),
					serviceContext.getCompanyId());
		}

		// Aggiornamento stato pratica con commenti
		String note = "Pratica inoltrata a Responsabile " + responsabileUser.getFullName();
		richiestaLocalService.updateStatoRichiesta(richiestaId, StatoRichiesta.IN_LAVORAZIONE.name(), note);
	}

	/**
	 *
	 * @param richiestaId
	 * @param taskId
	 * @param commento
	 * @param formIntegrativiIds
	 * @param fileEntryIds
	 * @param serviceContext
	 * @throws Exception
	 */
	public void richiediIntegrazioni(String tenantId, long richiestaId, String taskId, String commento, List<Long> formIntegrativiIds, List<String> fileEntryIds, ServiceContext serviceContext, String codiceOtpFirma, String password) throws
			FirmaDigitaleRemotaException, KosmosException, DataAccessException, PortalException {

		log.info("Avvio richiesta integrazione per richiestaId: "+richiestaId);

		if (formIntegrativiIds == null || formIntegrativiIds.isEmpty()) {
			throw new PortalException("Nessun form integrativo selezionato per la richiesta: ID RICHIESTA " + richiestaId);
		}

		User currentUser = userLocalService.getUser(serviceContext.getUserId());
		long commentoRichiestaId = 0;

        // Creazione istanze form aggiuntive
        Richiesta richiesta = richiestaLocalService.getRichiesta(richiestaId);
        Organization siteOrganization = organizationUtility.getSiteOrganization(richiesta.getGroupId());
        ServizioEnte servizioEnte = servizioEnteLocalService.getServizioEnte(new ServizioEntePK(richiesta.getServizioId(), siteOrganization.getOrganizationId()));

        if (Validator.isNotNull(commento)) {
            commentoRichiestaId = commentoRichiestaLocalService.createCommentoRichiesta(commento, taskId, true, richiestaId, currentUser.getUserId(), currentUser.getFullName(), serviceContext.getScopeGroupId(),
                    serviceContext.getCompanyId());
        }

        List<IstanzaForm> istanzaForms = new ArrayList<IstanzaForm>();
        for (Long formId : formIntegrativiIds) {
            IstanzaForm istanzaForm = istanzaFormLocalService.createIstanzaForm(null, formId, richiestaId, richiesta.getUserId(), richiesta.getUserName(), richiesta.getGroupId(), richiesta.getCompanyId(),
                    StatoIntegrazione.NON_VALIDATA.name(), commentoRichiestaId);
            istanzaForms.add(istanzaForm);
        }

        if(servizioEnte.isAbilitaProtocollazioneSoccorsoIstruttorio()){
            if(ListUtil.isNotNull(istanzaForms) && ListUtil.isNotEmpty(istanzaForms)){
                for(IstanzaForm istanzaForm : istanzaForms){
                    if(Validator.isNotNull(istanzaForm)) {
						try {
							protocollazioneIntegrazioniService.protocollaRichiestaIntegrazione(servizioEnte, istanzaForm,
									Long.valueOf(tenantId), serviceContext.getPortalURL(), commentoRichiestaId,
									currentUser.getUserId(), codiceOtpFirma, password);
						} catch (FirmaDigitaleRemotaException e) {
							try {
								for(IstanzaForm istanzaFormCreata : istanzaForms){
									if(Validator.isNotNull(istanzaFormCreata)){
										istanzaFormLocalService.deleteIstanzaForm(istanzaFormCreata);
										if(commentoRichiestaId > 0){
											commentoRichiestaLocalService.deleteCommentoRichiesta(commentoRichiestaId);
										}
									}
								}
							} catch (Exception rollbackEx) {
								log.error("Errore durante il rollback per FirmaDigitaleRemotaException, richiesta ID: " + richiestaId, rollbackEx);
							}
							throw e;
						} catch (KosmosException e) {
							try {
								for(IstanzaForm istanzaFormCreata : istanzaForms){
									if(Validator.isNotNull(istanzaFormCreata)){
										istanzaFormLocalService.deleteIstanzaForm(istanzaFormCreata);
										if(commentoRichiestaId > 0){
											commentoRichiestaLocalService.deleteCommentoRichiesta(commentoRichiestaId);
										}
									}
								}
							} catch (Exception rollbackEx) {
								log.error("Errore durante il rollback per KosmosException, richiesta ID: " + richiestaId, rollbackEx);
							}
							throw e;
						} catch (DataAccessException e) {
							try {
								for(IstanzaForm istanzaFormCreata : istanzaForms){
									if(Validator.isNotNull(istanzaFormCreata)){
										istanzaFormLocalService.deleteIstanzaForm(istanzaFormCreata);
										if(commentoRichiestaId > 0){
											commentoRichiestaLocalService.deleteCommentoRichiesta(commentoRichiestaId);
										}
									}
								}
							} catch (Exception rollbackEx) {
								log.error("Errore durante il rollback per DataAccessException, richiesta ID: " + richiestaId, rollbackEx);
							}
							throw e;
						} catch(Exception e){
                            log.error("richiediIntegrazioni :: errore per richiesta ID " + richiestaId, e);
                            // Rollback integrazioni
                            try {
                                for(IstanzaForm istanzaFormCreata : istanzaForms){
                                    if(Validator.isNotNull(istanzaFormCreata)){
                                        istanzaFormLocalService.deleteIstanzaForm(istanzaFormCreata);
                                        if(commentoRichiestaId > 0){
                                            commentoRichiestaLocalService.deleteCommentoRichiesta(commentoRichiestaId);
                                        }
                                    }
                                }
                            } catch (Exception rollbackEx) {
                                log.error("Errore durante il rollback per Exception generica, richiesta ID: " + richiestaId, rollbackEx);
                            }
                            // Cerca ricorsivamente se l'eccezione originale è una delle nostre eccezioni custom
                            Throwable cause = e;
                            while (cause != null) {
                                if (cause instanceof FirmaDigitaleRemotaException) {
                                    throw (FirmaDigitaleRemotaException) cause;
                                } else if (cause instanceof KosmosException) {
                                    throw (KosmosException) cause;
                                } else if (cause instanceof DataAccessException) {
                                    throw (DataAccessException) cause;
                                }
                                cause = cause.getCause();
                            }
                            throw new DataAccessException("Si è verificato un errore durante l'elaborazione della richiesta. Si prega di riprovare più tardi.", e);
                        }
                    }
                }
            }
        }

        if (fileEntryIds != null && !fileEntryIds.isEmpty()) {
            allegatoRichiestaLocalService.updateVisibilitaAllegatiRichiesta(fileEntryIds, true);
        }

		// Completa task
		List<Task> tasksByBusinessKey = camundaClient.getTasksByBusinessKey(tenantId, String.valueOf(richiestaId));
		if (tasksByBusinessKey != null) {

			for (Task task : tasksByBusinessKey) {
				if (taskId.equalsIgnoreCase(task.getId()) && String.valueOf(currentUser.getUserId()).equalsIgnoreCase(task.getAssignee())) {
					List<Entry<String, String>> variables = new ArrayList<Entry<String, String>>();
					camundaClient.completeTask(taskId, variables);
				}
			}
		}

		// Aggiornamento stato richiesta


		camundaClient.updateProcessInstanceVariableByBusinessKey(richiesta.getProcessInstanceId(), CustomProcessVariables.STATO_RICHIESTA, StatoRichiesta.ATTESA_INTEGRAZIONI.name(),
				CustomProcessVariables.TYPE_STRING);

		richiestaLocalService.updateStatoRichiesta(richiestaId, StatoRichiesta.ATTESA_INTEGRAZIONI.name());
		// invio email al cittadino
		try {
			User userRichiesta = userLocalService.getUser(richiesta.getUserId());
			String statoRichiestaLabel = getStatoRichiestaLabelValue(richiesta.getStato(), serviceContext.getLocale());

			AccountDto emailAccount = null;
			if (servizioEnte.isMailEnabled()) {
                KeystoreCryptoUtilProps keystoreUtil = new KeystoreCryptoUtilProps();
                String passwordDec = keystoreUtil.decrypt(servizioEnte.getMailPassword());

				emailAccount = new AccountDto();
				emailAccount.setHost(servizioEnte.getMailHost());
				emailAccount.setPort(servizioEnte.getMailPort());
				emailAccount.setProtocol(servizioEnte.getMailProtocol());
				emailAccount.setUsername(servizioEnte.getMailUsername());
				emailAccount.setPassword(passwordDec);
				emailAccount.setSocketPort(servizioEnte.getMailSocketFactoryPort());
				emailAccount.setAuth(String.valueOf(servizioEnte.getMailAuth()));
				emailAccount.setStarttls(servizioEnte.getMailStartTlsEnabled());
				emailAccount.setDebug(servizioEnte.getMailDebug());
				emailAccount.setStarttlsRequired(servizioEnte.getMailStartTlsRequired());
				emailAccount.setSocketFactoryFallback(servizioEnte.getMailSocketFactoryPortFallback());
				emailAccount.setFrom(servizioEnte.getMailFrom());
				emailAccount.setSslProtocols(servizioEnte.getMailProtocols());
			}

			communicationService.sendNotificaIntegrazioneCommunication(getNomeOrganizzazione(richiesta.getGroupId()), richiesta.getRichiestaId(), richiesta.getOggetto(), statoRichiestaLabel, getUtente(userRichiesta), richiesta.getCompanyId(), richiesta.getGroupId(), richiesta.getServizioId(), siteOrganization.getOrganizationId(), emailAccount);
		} catch (Exception e) {
			log.error("Errore nell'invio della comunicazione", e);
		}
	}

